bool Audio::loadClip(std::vector<float>&target,const std::string&relativePath){auto asset=embeddedAsset(relativePath);if(!asset)return false;SDL_AudioSpec source{};Uint8*sourceData=nullptr;Uint32 sourceBytes=0;if(!SDL_LoadWAV_IO(SDL_IOFromConstMem(asset.data,asset.size),true,&source,&sourceData,&sourceBytes))return false;SDL_AudioSpec desired{SDL_AUDIO_F32,1,(int)rate_};Uint8*converted=nullptr;int convertedBytes=0;bool ok=SDL_ConvertAudioSamples(&source,sourceData,(int)sourceBytes,&desired,&converted,&convertedBytes);SDL_free(sourceData);if(!ok)return false;target.resize(convertedBytes/(int)sizeof(float));std::memcpy(target.data(),converted,convertedBytes);SDL_free(converted);return true;}
bool Audio::init(){SDL_AudioSpec spec{SDL_AUDIO_F32,1,(int)rate_};device_=SDL_OpenAudioDevice(SDL_AUDIO_DEVICE_DEFAULT_PLAYBACK,&spec);if(!device_)return false;for(auto&stream:streams_){stream=SDL_CreateAudioStream(&spec,nullptr);if(!stream){shutdown();return false;}}if(!SDL_BindAudioStreams(device_,streams_.data(),(int)streams_.size())){shutdown();return false;}loadClip(clips_[Shot],"assets/audio/pistol.wav");loadClip(clips_[Reload],"assets/audio/reload.wav");loadClip(clips_[Melee],"assets/audio/melee.wav");loadClip(clips_[Hit],"assets/audio/monster_hurt.wav");loadClip(clips_[Leech],"assets/audio/creature_scary.wav");loadClip(clips_[PlayerHurt],"assets/audio/player_hurt.wav");loadClip(clips_[Ring],"assets/audio/phone_ring.wav");loadClip(clips_[Drop],"assets/audio/drop.wav");loadClip(clips_[Pickup],"assets/audio/pickup.wav");loadClip(clips_[Death],"assets/audio/creature_scary.wav");loadClip(clips_[Step],"assets/audio/footstep_0.wav");loadClip(alternateStep_,"assets/audio/footstep_1.wav");SDL_ResumeAudioDevice(device_);return true;}
void Audio::shutdown(){for(auto&clip:clips_)clip.clear();alternateStep_.clear();for(auto&stream:streams_){if(stream){SDL_DestroyAudioStream(stream);stream=nullptr;}}if(device_){SDL_CloseAudioDevice(device_);device_=0;}}
std::vector<float> Audio::synth(int sound){float duration=.15f,freq=220,noise=.1f;switch(sound){case Shot:duration=.22f;freq=75;noise=.9f;break;case Reload:duration=.18f;freq=520;break;case Melee:duration=.16f;freq=120;noise=.35f;break;case Hit:duration=.1f;freq=85;noise=.5f;break;case Leech:duration=.35f;freq=55;noise=.25f;break;case PlayerHurt:duration=.32f;freq=42;noise=.5f;break;case Ring:duration=.8f;freq=740;break;case Radio:duration=.65f;freq=330;noise=.45f;break;case Drop:duration=.2f;freq=64;noise=.65f;break;case Pickup:duration=.25f;freq=880;break;case Victory:duration=1.1f;freq=440;break;case Death:duration=1.2f;freq=90;noise=.2f;break;case Step:duration=.09f;freq=48;noise=.65f;break;}int n=int(duration*rate_);std::vector<float>v(n);uint32_t r=uint32_t(sound*71237+91);for(int i=0;i<n;i++){float t=float(i)/rate_,env=std::pow(1.f-float(i)/n,sound==Ring?1.f:2.f);r=r*1664525u+1013904223u;float nz=(float(int(r>>16)-32768)/32768.f);float wave=std::sin(6.2831853f*freq*t+(sound==Victory?18*t*t:0));if(sound==Ring)wave*=((int(t*5)&1)==0);if(sound==Death)wave=std::sin(6.283f*(freq*(1-t*.6f))*t);v[i]=(wave*(1-noise)+nz*noise)*env*.32f;}return v;}
void Audio::play(int sound,float volume){if(!device_||sound<0||sound>=SoundCount)return;int channel=sound==Step?1:(sound==Shot||sound==Reload||sound==Melee?0:(sound==Ring||sound==Radio?3:2));SDL_AudioStream*out=streams_[channel];if(!out)return;const std::vector<float>*loaded=&clips_[sound];if(sound==Step&&!alternateStep_.empty()){loaded=alternateStepNext_?&alternateStep_:&clips_[Step];alternateStepNext_=!alternateStepNext_;}std::vector<float>v=loaded->empty()?synth(sound):*loaded;for(float&x:v)x*=volume;SDL_ClearAudioStream(out);SDL_PutAudioStreamData(out,v.data(),int(v.size()*sizeof(float)));}
